def embedded_image(b64, width_mm, h_align):
    """base64 이미지를 가로 폭(mm)에 맞춰 불러온다. 세로는 원본 비율로 계산하므로 모양이 변하지 않는다."""
    raw = base64.b64decode("".join(b64.split()))
    iw, ih = ImageReader(io.BytesIO(raw)).getSize()
    w = width_mm * mm
    img = Image(io.BytesIO(raw), width=w, height=w * ih / iw)
    img.hAlign = h_align
    return img


def brand_header(width=None):
    """첫 쪽 맨 위에 넣는 로고(왼쪽) + 펭귄 이미지(오른쪽). 실패해도 요약 PDF 만들기는 계속한다."""
    try:
        logo = embedded_image(LOGO_B64, LOGO_WIDTH_MM, "LEFT")
        peng = embedded_image(PENGUIN_B64, PENGUIN_WIDTH_MM, "RIGHT")
    except Exception as ex:
        print(f"[주의] 내장 이미지를 불러오지 못했습니다: {ex}")
        return []
    t = Table([[logo, peng]], colWidths=[(width or CW) - PENGUIN_WIDTH_MM * mm, PENGUIN_WIDTH_MM * mm])
    t.setStyle(TableStyle([("VALIGN", (0, 0), (-1, -1), "TOP"),
                           ("LEFTPADDING", (0, 0), (-1, -1), 0), ("RIGHTPADDING", (0, 0), (-1, -1), 0),
                           ("TOPPADDING", (0, 0), (-1, -1), 0), ("BOTTOMPADDING", (0, 0), (-1, -1), 0)]))
    return [t, Spacer(1, 4 * mm)]


