# 항목별 (좌/우, 글자 기준선 y) — 원본 화면 좌표(px). 좌측 글자는 x=158부터, 금액은 x=490에서 오른쪽 맞춤.
BODY_LEFT_X, BODY_LEFT_R = 158, 490
BODY_RIGHT_X, BODY_RIGHT_R = 1175, 1505
BODY_BASE = {
    "뇌출혈": ("L", 287), "뇌경색": ("L", 345), "뇌혈관질환": ("L", 403), "산정특례(뇌)": ("L", 462),
    "일반암": ("L", 594), "고액암": ("L", 653), "소액암": ("L", 711), "표적항암": ("L", 769),
    "당뇨": ("L", 890),
    "LTC(치매)": ("R", 285), "중등도치매": ("R", 346), "경도치매": ("R", 408),
    "급성심근경색": ("R", 542), "허혈성심장질환": ("R", 603), "산정특례(심장)": ("R", 664),
    "말기폐질환": ("R", 789), "말기간질환": ("R", 847), "말기신부전증": ("R", 906),
}
BODY_TEXT_PX = 26
BODY_STATUS_COLOR = {"충분": "#008973", "부족": "#E28E3A", "미보장": "#C64647"}
BODY_LABEL_COLOR = colors.HexColor("#111111")
BODY_ALT = {"표적항암": "表적항암"}           # 원본 글자가 한자로 되어 있는 경우도 같은 항목으로 본다


class BodyMap(Flowable):
    """내장 그림 위에 항목명·금액을 원본과 같은 자리에 그린다."""

    def __init__(self, body, width):
        super().__init__()
        self.body, self.k = body, width / BODY_PIC_W
        self.width, self.height = width, BODY_PIC_H * self.k
        self.reader = ImageReader(io.BytesIO(base64.b64decode("".join(BODY_PIC_B64.split()))))

    def wrap(self, aw, ah):
        return self.width, self.height

    def _font(self, text):
        if GLYPHS and any(ord(ch) >= 128 and ord(ch) not in GLYPHS for ch in text):
            return CID_FALLBACK
        return FONT

    def draw(self):
        c, k = self.canv, self.k
        c.drawImage(self.reader, 0, 0, self.width, self.height)
        size = BODY_TEXT_PX * k
        for lab, (side, base) in BODY_BASE.items():
            val, status = self.body[lab]
            y = self.height - (base - BODY_PIC_Y0) * k
            x_lab, x_val = (BODY_LEFT_X, BODY_LEFT_R) if side == "L" else (BODY_RIGHT_X, BODY_RIGHT_R)
            c.setFillColor(BODY_LABEL_COLOR)
            c.setFont(self._font(lab), size)
            c.drawString((x_lab - BODY_PIC_X0) * k, y, lab)
            c.setFillColor(colors.HexColor(BODY_STATUS_COLOR[status]))
            c.setFont(FONT, size)
            c.drawRightString((x_val - BODY_PIC_X0) * k, y, val)


