def story_cover(cv, basis, entries):
    """로고·펭귄 이미지는 build_pdf 가 표지 위에 따로 넣는다 (축소 대상에서 제외)."""
    st = [Spacer(1, 6 * mm), P(f"{esc(cv['name'])} 고객님을 위한", "cover_sub"), P("보장분석 요약 보고서", "cover_title"),
          HRFlowable(width=70 * mm, thickness=3, color=NAVY, hAlign="LEFT"), Spacer(1, 8 * mm)]
    info = [[cell(f"<b>{lab}</b>", 9, 0, color=GRAY), cell(esc(cv[key]), 9)]
            for lab, key in (("Financial Planner", "fp"), ("소속", "branch"), ("H.P", "phone"), ("Email", "email"))
            if cv.get(key)]
    if info:
        t = Table(info, colWidths=[42 * mm, 90 * mm], hAlign="LEFT")
        t.setStyle(TableStyle([("LINEBELOW", (0, 0), (-1, -1), 0.3, LINE), ("TOPPADDING", (0, 0), (-1, -1), 3),
                               ("BOTTOMPADDING", (0, 0), (-1, -1), 3), ("LEFTPADDING", (0, 0), (-1, -1), 0)]))
        st += [t, Spacer(1, 8 * mm)]
    items = [e for e in entries if e["kind"] != "cover"]
    half = (len(items) + 1) // 2
    rows = []
    for i in range(half):
        l = items[i]
        r = items[half + i] if half + i < len(items) else None
        rows.append([str(l["n"]), esc(l["title"]), str(r["n"]) if r else "", esc(r["title"]) if r else ""])
    st.append(data_table(["쪽", "구성", "쪽", "구성"], rows, fit([9, 79, 9, 79]), aligns=[1, 0, 1, 0], size=8))
    st += [Spacer(1, 5 * mm), P(f"분석 기준일 {basis or cv.get('print_date', '')} · 출력일 {cv.get('print_date', '')}", "sub")]
    return st


def story_enrollment(d, src, name):
    info, cs = d["info"], d["contracts"]
    st = page_header("보험 가입 현황", src, f"{esc(name)} ({info['birth']}생)")
    st.append(kpi([("보험나이", f"{info['ins_age']}세"), ("상령일", info["age_date"]),
                   ("유지계약", f"{info['n_contracts']}건"), ("월보험료", f"{info['monthly']}원"),
                   ("기납입보험료", f"{info['paid_total']}원")]))
    st.append(Spacer(1, 6))
    same = all(c["holder"] == c["insured"] == name and c["coinsured"] == "-" for c in cs)
    has_last = any(c["last"] not in ("", "-") for c in cs)
    head = ["번호", "구분", "보험사", "상품명", "계약일", "만기", "월보험료(원)", "납입횟수"]
    wid = [7, 10, 19, 0, 19, 17, 18, 19]
    if has_last:
        head.append("최종월도")
        wid.append(15)
    head.append("기납입(원)")
    wid.append(20)
    if not same:
        head.append("계약자 / 주피 / 종피")
        wid.append(26)
    wid[3] = max(178 - sum(wid), 24)
    rows = []
    for c in cs:
        r = [c["no"], esc(c["origin"]), esc(c["company"]), esc(c["name"]), c["date"], esc(c["expiry"]),
             c["premium"], esc(c["count"])]
        if has_last:
            r.append("" if c["last"] == "-" else esc(c["last"]))
        r.append(c["paid"])
        if not same:
            r.append(f"{esc(c['holder'])} / {esc(c['insured'])} / {esc(c['coinsured'])}")
        rows.append(r)
    aligns = [1, 1, 0, 0, 1, 1, 2, 1] + ([1] if has_last else []) + [2] + ([0] if not same else [])
    st.append(data_table(head, rows, fit(wid), aligns=aligns, size=7.2))
    if same:
        st += [Spacer(1, 4), P(f"계약자·피보험자: {esc(name)} (전 계약 동일)", "sub")]
    return st


def story_generation(d, src):
    cnt, members = d["counts"], d["members"]
    st = page_header("세대 분석", src, "구성원별 준비 금액 · 단위: 만원")
    if cnt:
        st.append(data_table(["구분", "전체", "교보생명", "생명보험", "손해보험", "공제/우체국"],
                             [["유지계약"] + [f"{cnt[k]}건" for k in ("total", "kyobo", "life", "nonlife", "mutual")]],
                             fit([26, 30, 30, 30, 30, 30]), aligns=[1] * 6, size=8))
        st.append(Spacer(1, 6))
    ra, sa = grouped_rows(GROUPS_A, lambda i, l: [esc(m["a"][i]) for m in members])
    rb, sb = grouped_rows(GROUPS_B, lambda i, l: [esc(m["b"][i]) for m in members], start=len(ra))
    head = ["구분", "항목"] + [f"{esc(m['name'])}<br/>({m['age']}세)" for m in members]
    wid = [22, 34] + [122 / len(members)] * len(members)
    st.append(data_table(head, ra + rb, fit(wid), aligns=[0, 0] + [2] * len(members), size=7.5, spans=sa + sb))
    return st


def story_products(d, src, title, labels, groups):
    n = len(labels)
    need, prep, short = d["need"], d["prep"], d["short"]
    stat = [status_of(prep[i], short[i]) for i in range(n)]
    cnt = {k: stat.count(k) for k in ("적정", "부족", "미보장")}
    st = page_header(title, src, "단위: 만원")
    if d["head"]:
        h = d["head"]
        st.append(kpi([("분석항목(전체)", f"{h['total']}개"), ("적정보장", f"{h['ok']}개", C_OK),
                       ("부족보장", f"{h['low']}개", C_LOW), ("미보장", f"{h['none']}개", C_NONE)]))
    else:
        st.append(kpi([("이 쪽 분석항목", f"{n}개"), ("적정보장", f"{cnt['적정']}개", C_OK),
                       ("부족보장", f"{cnt['부족']}개", C_LOW), ("미보장", f"{cnt['미보장']}개", C_NONE)]))
    st.append(Spacer(1, 6))
    shown = [(k, p) for k, p in enumerate(d["products"], 1) if any(v != "-" for v in p["vals"])]
    m = len(shown)
    fixed = [16, 27, 14, 14, 14, 13]
    pw = max(min((178 - sum(fixed)) / m, 15), 6) if m else 0
    size = num_size(pw) if m else 7.5
    head = ["구분", "항목", "필요", "준비", "부족", "상태"] + [str(k) for k, _ in shown]
    rows, spans = grouped_rows(groups, lambda i, l: [esc(need[i]), esc(prep[i]), esc(short[i])])
    for i, r in enumerate(rows):
        r.insert(5, status_cell(stat[i]))
        r.extend(esc(p["vals"][i]) for _, p in shown)
    st.append(data_table(head, rows, fit(fixed + [pw] * m), aligns=[0, 0, 2, 2, 2, 1] + [2] * m, size=size,
                         spans=spans))
    if shown:
        st.append(Spacer(1, 7))
        prow = [[str(k), esc(p["company"]), esc(p["name"]), p["premium"],
                 esc("종신" if p["expiry"] == "종신" else p["expiry"])] for k, p in shown]
        st.append(data_table(["번호", "보험사", "상품명", "월보험료", "만기"], prow, fit([10, 30, 76, 28, 24]),
                             aligns=[1, 0, 0, 2, 1], size=7.5))
    return st


def story_body(d, src):
    body = d["body"]
    if all(lab in body for lab in BODY_BASE):                # 원본 모양 그대로 (내장 그림)
        try:
            return page_header("신체부위별 보장현황", src) + [BodyMap(body, CW)]
        except Exception as ex:                              # 그림을 읽지 못하면 표로 대체
            print(f"[주의] 내장 그림을 불러오지 못해 표로 대체합니다: {ex}")
    st = page_header("신체부위별 보장현황", src, "단위: 만원")
    cnt = {"충분": 0, "부족": 0, "미보장": 0}
    for _, s_ in body.values():
        cnt[s_] += 1
    st.append(kpi([("충분", f"{cnt['충분']}개", C_OK), ("부족", f"{cnt['부족']}개", C_LOW),
                   ("미보장", f"{cnt['미보장']}개", C_NONE)]))
    st.append(Spacer(1, 6))
    rows, spans = grouped_rows(BODY_GROUPS, lambda i, l: [esc(body[l][0]), status_cell(body[l][1])])
    st.append(data_table(["구분", "항목", "금액", "상태"], rows, fit([30, 62, 42, 30]), aligns=[0, 0, 2, 1], size=8.5,
                         spans=spans))
    return st


def age_groups(rows):
    groups = []
    for age, vals in rows:
        if groups and groups[-1][1] == vals:
            groups[-1][0].append(age)
        else:
            groups.append(([age], vals))
    return groups


def story_ages(title, src, rows, labels, groups):
    st = page_header(title, src, "연령별 보장 금액 · 단위: 만원")
    ag = age_groups(rows)
    g = len(ag)
    pw = max(min((178 - 52) / g, 22), 6)
    head = ["구분", "항목"] + [esc(a[0]) if len(a) == 1 else f"{esc(a[0])}~<br/>{esc(a[-1])}" for a, _ in ag]
    table_rows, spans = grouped_rows(groups, lambda i, l: [esc(v[i]) for _, v in ag])
    st.append(data_table(head, table_rows, fit([20, 32] + [pw] * g), aligns=[0, 0] + [2] * g, size=num_size(pw),
                         spans=spans))
    return st


# ----------------------------------------------------------------------------
# 6. PDF 조립
# ----------------------------------------------------------------------------
def draw_footer(canvas, doc):
    pw, ph = canvas._pagesize
    mx, ly = (W_MARGIN_X, 12 * mm) if pw > ph else (MARGIN_X, 14 * mm)
    canvas.saveState()
    canvas.setStrokeColor(colors.HexColor("#D1D5DB"))
    canvas.line(mx, ly, pw - mx, ly)
    canvas.setFont(FONT, 7.5)
    canvas.setFillColor(GRAY)
    canvas.drawString(mx, ly - 4 * mm, doc.footer_left)
    canvas.drawRightString(pw - mx, ly - 4 * mm, f"{canvas.getPageNumber()} / {doc.total_pages}")
    canvas.restoreState()


def make_story(e, ctx):
    k, n, d = e["kind"], e["n"], e["data"]
    if e["mode"] != "전용":
        return story_generic(e)
    if k == "cover":
        return story_cover(d, ctx["basis"], ctx["entries"])
    if k == "enrollment":
        return story_enrollment(d, n, ctx["name"])
    if k == "generation":
        return story_generation(d, n)
    if k == "products":
        return story_products(d["d"], n, e["title"], d["labels"], d["groups"])
    if k == "body":
        return story_body(d, n)
    if k == "ages":
        return story_ages(e["title"], n, d["rows"], d["labels"], d["groups"])
    return story_generic(e)


def natural_height(flowables, width=None):
    h = 0
    for f in flowables:
        h += f.wrap(width or CW, 10 ** 6)[1] + f.getSpaceBefore() + f.getSpaceAfter()
    return h


def is_wide(e):
    """범용 요약 쪽(전용 양식이 없거나 읽기에 실패한 쪽)은 16:9 가로 쪽으로 만든다."""
    return e["mode"] != "전용"


def build_pdf(entries, ctx, out_path):
    build_styles()
    ctx["entries"] = entries
    cv = ctx["cover"]
    stories = [make_story(e, ctx) for e in entries]
    wides = [is_wide(e) for e in entries]
    for e, st, wd in zip(entries, stories, wides):
        h = natural_height(st, WCW if wd else CW)
        fh = WFH if wd else FH
        if h > fh * 1.5:
            print(f"[주의] 원본 p.{e['n']}: 내용이 많아 약 {int(fh / h * 100)}% 크기로 축소됩니다.")
    name = ctx["name"]
    doc = BaseDocTemplate(str(out_path), pagesize=A4, title=f"{name} 보장분석 요약 보고서",
                          author=cv.get("fp", ""), leftMargin=MARGIN_X, rightMargin=MARGIN_X)
    doc.total_pages = len(entries)
    doc.footer_left = (f"{name} 고객님 보장분석 요약 · {ctx['basis'] or cv.get('print_date', '')} 기준 · "
                       "보험금 지급 근거 아님, 약관·증권 우선")
    main_t = PageTemplate(id="main", pagesize=A4, onPage=draw_footer,
                          frames=[Frame(MARGIN_X, FRAME_BOTTOM, CW, FH, leftPadding=0, rightPadding=0,
                                        topPadding=0, bottomPadding=0)])
    wide_t = PageTemplate(id="wide", pagesize=(WIDE_W, WIDE_H), onPage=draw_footer,
                          frames=[Frame(W_MARGIN_X, W_BOTTOM, WCW, WFH, leftPadding=0, rightPadding=0,
                                        topPadding=0, bottomPadding=0)])
    doc.addPageTemplates([wide_t, main_t] if wides and wides[0] else [main_t, wide_t])   # 첫 쪽 양식이 먼저
    story = []
    for i, st in enumerate(stories):
        cw, fh = (WCW, WFH) if wides[i] else (CW, FH)
        if i == 0:
            brand = brand_header(cw)                       # 첫 쪽에는 항상 로고·펭귄을 넣고, 이 부분은 축소하지 않는다
            brand_h = natural_height(brand, cw) if brand else 0
            story.extend(brand)
            story.append(KeepInFrame(cw, fh - brand_h - 2, st, mode="shrink"))   # 이미지 아래 내용만 축소
        else:
            story.append(KeepInFrame(cw, fh, st, mode="shrink"))                 # 넘치면 축소해서 한 쪽에 맞춤
        if i < len(stories) - 1:
            story.append(NextPageTemplate("wide" if wides[i + 1] else "main"))
            story.append(PageBreak())
    doc.build(story)


def convert(src, out, force_generic=False):
    """PDF 한 개를 요약 PDF로 변환한다. 진행 내용은 print 로 알린다. -> (요약 쪽수, 원본 쪽수)"""
    register_fonts()
    with pdfplumber.open(str(src)) as pdf:
        n_src = len(pdf.pages)
        entries, ctx = analyze_pdf(pdf, force_generic)
        print(f"[원본] {n_src}쪽 — 쪽별 처리")
        for e in entries:
            print(f"  p.{e['n']:>2}  {e['title']}  [{e['mode']}]" + (f"  ※ {e['note']}" if e["note"] else ""))
        build_pdf(entries, ctx, out)
    n_out = None
    try:
        from pypdf import PdfReader
        n_out = len(PdfReader(str(out)).pages)
        print(f"[완료] {out}  (요약 {n_out}쪽 / 원본 {n_src}쪽)")
        if n_out != n_src:
            print("[경고] 쪽수가 원본과 다릅니다. 내용이 한 쪽을 넘쳤는지 확인하세요.")
    except ImportError:
        print(f"[완료] {out}")
    return n_out, n_src


# ----------------------------------------------------------------------------
# 7. PDF 선택 창 (tkinter)
# ----------------------------------------------------------------------------
def open_path(path):
    """운영체제 기본 프로그램으로 파일/폴더 열기."""
    path = str(path)
    if sys.platform.startswith("win"):
        os.startfile(path)                                    # noqa: S606 (Windows 전용)
    elif sys.platform == "darwin":
        subprocess.Popen(["open", path])
    else:
        subprocess.Popen(["xdg-open", path])


class _QueueWriter(io.TextIOBase):
    """print 출력을 창의 로그로 보내기 위한 쓰기 도우미."""

    def __init__(self, q):
        self.q = q

    def write(self, text):
        if text:
            self.q.put(("log", text))
        return len(text)


class App:
    def __init__(self, root):
        self.root = root
        self.q = queue.Queue()
        self.result = None
        self.running = False
        self.finished = False                 # (테스트·점검용) 한 번 변환이 끝나면 True
        self.manual_out = False               # 저장 위치를 직접 골랐는가
        self.last_dir = str(Path.home())
        self.src_var, self.out_var = tk.StringVar(), tk.StringVar()
        self.gen_var = tk.BooleanVar(value=False)
        self.status_var = tk.StringVar(value="PDF를 선택하세요.")

        root.title("보장분석 요약 PDF 만들기")
        root.geometry("760x540")
        root.minsize(640, 460)
        frm = ttk.Frame(root, padding=14)
        frm.pack(fill="both", expand=True)
        frm.columnconfigure(1, weight=1)
        frm.rowconfigure(5, weight=1)

        ttk.Label(frm, text="교보생명 보장분석 보고서 PDF를 골라 쪽별 1:1 요약 PDF를 만듭니다.",
                  foreground="#555555").grid(row=0, column=0, columnspan=3, sticky="w", pady=(0, 10))

        ttk.Label(frm, text="원본 PDF").grid(row=1, column=0, sticky="w", padx=(0, 8))
        ttk.Entry(frm, textvariable=self.src_var, state="readonly").grid(row=1, column=1, sticky="ew")
        self.btn_pick = ttk.Button(frm, text="PDF 선택...", command=self.pick_src)
        self.btn_pick.grid(row=1, column=2, padx=(8, 0))

        ttk.Label(frm, text="저장 위치").grid(row=2, column=0, sticky="w", padx=(0, 8), pady=(8, 0))
        ttk.Entry(frm, textvariable=self.out_var).grid(row=2, column=1, sticky="ew", pady=(8, 0))
        self.btn_out = ttk.Button(frm, text="저장 위치...", command=self.pick_out)
        self.btn_out.grid(row=2, column=2, padx=(8, 0), pady=(8, 0))

        self.chk = ttk.Checkbutton(frm, text="모든 쪽을 범용 요약으로 만들기 (점검용)", variable=self.gen_var)
        self.chk.grid(row=3, column=1, sticky="w", pady=(8, 0))

        bar = ttk.Frame(frm)
        bar.grid(row=4, column=0, columnspan=3, sticky="ew", pady=(12, 8))
        bar.columnconfigure(1, weight=1)
        self.btn_run = ttk.Button(bar, text="요약 PDF 만들기", command=self.start)
        self.btn_run.grid(row=0, column=0)
        self.progress = ttk.Progressbar(bar, mode="indeterminate")
        self.progress.grid(row=0, column=1, sticky="ew", padx=10)
        self.btn_open = ttk.Button(bar, text="요약 PDF 열기", command=self.open_result, state="disabled")
        self.btn_open.grid(row=0, column=2)
        self.btn_folder = ttk.Button(bar, text="폴더 열기", command=self.open_folder, state="disabled")
        self.btn_folder.grid(row=0, column=3, padx=(6, 0))

        box = ttk.Frame(frm)
        box.grid(row=5, column=0, columnspan=3, sticky="nsew")
        box.rowconfigure(0, weight=1)
        box.columnconfigure(0, weight=1)
        self.text = tk.Text(box, height=12, wrap="word", state="disabled", background="#F7F8FA", relief="flat",
                            borderwidth=1)
        sb = ttk.Scrollbar(box, command=self.text.yview)
        self.text.configure(yscrollcommand=sb.set)
        self.text.grid(row=0, column=0, sticky="nsew")
        sb.grid(row=0, column=1, sticky="ns")
        ttk.Label(frm, textvariable=self.status_var).grid(row=6, column=0, columnspan=3, sticky="w", pady=(8, 0))
        self._center()
        self.root.after(100, self._poll)

    # ---- 화면 도우미
    def _center(self):
        self.root.update_idletasks()
        w, h = self.root.winfo_width(), self.root.winfo_height()
        x = (self.root.winfo_screenwidth() - w) // 2
        y = (self.root.winfo_screenheight() - h) // 3
        self.root.geometry(f"+{max(x, 0)}+{max(y, 0)}")

    def log(self, text):
        self.text.configure(state="normal")
        self.text.insert("end", text)
        self.text.see("end")
        self.text.configure(state="disabled")

    def set_busy(self, busy):
        self.running = busy
        state = "disabled" if busy else "normal"
        for w in (self.btn_pick, self.btn_out, self.btn_run, self.chk):
            w.configure(state=state)
        if busy:
            self.progress.start(12)
            for w in (self.btn_open, self.btn_folder):
                w.configure(state="disabled")
        else:
            self.progress.stop()

    # ---- 파일 선택
    def set_source(self, path):
        path = str(path)
        self.src_var.set(path)
        self.last_dir = str(Path(path).parent)
        if not self.manual_out:
            self.out_var.set(str(Path(path).with_name(Path(path).stem + "_요약.pdf")))
        self.status_var.set("[요약 PDF 만들기]를 누르세요.")

    def pick_src(self):
        path = filedialog.askopenfilename(title="원본 보장분석 보고서 PDF 선택", initialdir=self.last_dir,
                                          filetypes=[("PDF 파일", "*.pdf"), ("모든 파일", "*.*")])
        if path:
            self.set_source(path)

    def pick_out(self):
        cur = Path(self.out_var.get()) if self.out_var.get() else None
        path = filedialog.asksaveasfilename(title="요약 PDF 저장 위치", defaultextension=".pdf",
                                            initialdir=str(cur.parent) if cur else self.last_dir,
                                            initialfile=cur.name if cur else "요약.pdf",
                                            filetypes=[("PDF 파일", "*.pdf")])
        if path:
            self.out_var.set(path)
            self.manual_out = True

    # ---- 변환
    def start(self):
        if self.running:
            return
        src = Path(self.src_var.get().strip().strip('"'))
        if not src.is_file():
            messagebox.showwarning("PDF 선택", "먼저 원본 PDF를 선택하세요.")
            return
        if src.suffix.lower() != ".pdf":
            messagebox.showwarning("PDF 선택", "PDF 파일(.pdf)을 선택하세요.")
            return
        out = Path(self.out_var.get().strip().strip('"'))
        if not out.name:
            messagebox.showwarning("저장 위치", "저장할 파일 이름을 입력하세요.")
            return
        if out.suffix.lower() != ".pdf":
            out = out.with_suffix(".pdf")
            self.out_var.set(str(out))
        if out.resolve() == src.resolve():
            messagebox.showerror("저장 위치", "원본 PDF와 같은 파일에는 저장할 수 없습니다.\n저장 위치를 바꿔 주세요.")
            return
        if out.exists() and not self.manual_out:
            if not messagebox.askyesno("덮어쓰기", f"같은 이름의 파일이 이미 있습니다.\n덮어쓸까요?\n\n{out}"):
                return
        try:
            out.parent.mkdir(parents=True, exist_ok=True)
        except OSError as ex:
            messagebox.showerror("저장 위치", f"저장 폴더를 만들 수 없습니다.\n{ex}")
            return
        self.text.configure(state="normal")
        self.text.delete("1.0", "end")
        self.text.configure(state="disabled")
        self.finished = False
        self.result = None
        self.status_var.set("변환 중입니다...")
        self.set_busy(True)
        threading.Thread(target=self._worker, args=(src, out, self.gen_var.get()), daemon=True).start()

    def _worker(self, src, out, generic):
        try:
            with contextlib.redirect_stdout(_QueueWriter(self.q)):
                n_out, n_src = convert(src, out, generic)
            self.q.put(("done", (out, n_out, n_src)))
        except Exception as ex:                                    # 어떤 오류든 창에 보여 준다
            self.q.put(("log", traceback.format_exc()))
            self.q.put(("error", ex))

    def _poll(self):
        try:
            while True:
                kind, payload = self.q.get_nowait()
                if kind == "log":
                    self.log(payload)
                elif kind == "done":
                    self._on_done(*payload)
                elif kind == "error":
                    self._on_error(payload)
        except queue.Empty:
            pass
        self.root.after(100, self._poll)

    def _on_done(self, out, n_out, n_src):
        self.set_busy(False)
        self.finished = True
        self.result = Path(out)
        for w in (self.btn_open, self.btn_folder):
            w.configure(state="normal")
        same = (n_out is None) or (n_out == n_src)
        self.status_var.set(f"완료: 원본 {n_src}쪽 → 요약 {n_out if n_out is not None else '?'}쪽  |  {out}")
        if same:
            if messagebox.askyesno("완료", f"요약 PDF를 만들었습니다. ({n_src}쪽)\n{out}\n\n지금 열어 볼까요?"):
                self.open_result()
        else:
            messagebox.showwarning("쪽수 확인", f"원본 {n_src}쪽, 요약 {n_out}쪽으로 쪽수가 다릅니다.\n로그를 확인하세요.")

    def _on_error(self, ex):
        self.set_busy(False)
        self.finished = True
        self.status_var.set("오류가 발생했습니다. 아래 로그를 확인하세요.")
        hint = ""
        if isinstance(ex, PermissionError):
            hint = "\n\n저장하려는 PDF가 다른 프로그램에서 열려 있으면 닫고 다시 시도하세요."
        messagebox.showerror("변환 실패", f"{ex}{hint}")

    # ---- 결과 열기
    def open_result(self):
        if self.result and self.result.exists():
            open_path(self.result)

    def open_folder(self):
        if self.result:
            open_path(self.result.parent)


def run_gui():
    try:                                              # 윈도우 고해상도 화면에서 글자 흐림 방지
        import ctypes
        ctypes.windll.shcore.SetProcessDpiAwareness(1)
    except Exception:
        pass
    root = tk.Tk()
    App(root)
    root.mainloop()


def main():
    args = [a for a in sys.argv[1:] if not a.startswith("--")]
    force_generic = "--generic" in sys.argv
    if not args:                                      # 인자가 없으면 PDF 선택 창을 연다
        if tk is None:
            print("tkinter를 사용할 수 없어 창을 열 수 없습니다. 명령줄로 PDF 경로를 지정하세요.\n")
            print(__doc__)
            sys.exit(1)
        run_gui()
        return
    src = Path(args[0])
    out = Path(args[1]) if len(args) > 1 else src.with_name(src.stem + "_요약.pdf")
    convert(src, out, force_generic)


if __name__ == "__main__":
    main()
